import{_ as t,o as a,c as o,ah as s}from"./chunks/framework.BK78naE0.js";const i="/projects/JetMaxPro/en/latest/assets/image2.CXw07a-q.webp",r="/projects/JetMaxPro/en/latest/assets/image3.DbB1QQ8k.webp",n="data:image/png;base64,",l="/projects/JetMaxPro/en/latest/assets/image5.DtipY28k.webp",c="/projects/JetMaxPro/en/latest/assets/image6.Y9BV77Ey.webp",m="/projects/JetMaxPro/en/latest/assets/image7.IiytdAaV.webp",h="/projects/JetMaxPro/en/latest/assets/image8.BH-lBuM9.webp",p="/projects/JetMaxPro/en/latest/assets/image9.CL6E4h9U.webp",g="data:image/png;base64,",d="/projects/JetMaxPro/en/latest/assets/image3.C5abTGUy.webp",u="/projects/JetMaxPro/en/latest/assets/image4.InEIuIUt.webp",A="/projects/JetMaxPro/en/latest/assets/image5.DcLw8abS.webp",w="/projects/JetMaxPro/en/latest/assets/image6.B9lMQ4rl.webp",b="/projects/JetMaxPro/en/latest/assets/image7.B2yF1V2M.webp",y="/projects/JetMaxPro/en/latest/assets/image8.Cz6k2LqR.webp",f="/projects/JetMaxPro/en/latest/assets/image9.CXWIh5UC.webp",L=JSON.parse('{"title":"11. Monocular Camera Lesson","description":"","frontmatter":{},"headers":[],"relativePath":"docs/11.Monocular Camera Lesson.md","filePath":"docs/11.Monocular Camera Lesson.md"}'),x={name:"docs/11.Monocular Camera Lesson.md"};function _(k,e,C,P,z,M){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="_11-monocular-camera-lesson" tabindex="-1">11. Monocular Camera Lesson <a class="header-anchor" href="#_11-monocular-camera-lesson" aria-label="Permalink to &quot;11. Monocular Camera Lesson&quot;">​</a></h1><h2 id="_11-1-lesson-1-basic-usage-of-monocular-camera" tabindex="-1">11.1 Lesson 1 Basic Usage of Monocular Camera <a class="header-anchor" href="#_11-1-lesson-1-basic-usage-of-monocular-camera" aria-label="Permalink to &quot;11.1 Lesson 1 Basic Usage of Monocular Camera&quot;">​</a></h2><p>JetMax is loaded with USB monocular camera used to obtain the image transmitted by camera.</p><p>Monocular camera is capable of perceiving, surround view and monitoring. Compared with other camera, it features low latency, slight shaking, plug-and-play and tiny size.</p><p>This lesson demonstrates how to turn on camera through Jetson Nano to obtain the camera returned image. The instructions are as follow.</p><ol><li><p><strong>Connect to Jetson Nano</strong></p><p>Connect USB monocular camera to NO.1 interface as pictured.</p><img loading="lazy" height="245" width="533" class="common_img" src="'+i+'" style="width:800px;"><img loading="lazy" height="1616" width="1212" class="common_img" src="'+r+'" style="width:800px;" alt="20DE3879FBE3E72305D63AFE3F54A858"></li><li><p><strong>Turn on Camera</strong></p></li></ol><p><img loading="lazy" height="44" width="44" src="'+n+'" style="width:50px;">The input command should be case sensitive, and key words can be complemented by “<strong>Tab</strong>” key.</p><ol><li><p>Start JetMax, connect to ubuntu desktop through No Machine.</p></li><li><p>Click <img loading="lazy" height="98" width="119" class="inline-icon" src="'+l+'"> to open terminal.</p></li><li><p>Input command “<strong>rqt_image_view</strong>” and press Enter to open camera returned image</p><img loading="lazy" height="87" width="428" class="common_img" src="'+c+'" style="width:800px;"></li><li><p>Select “<strong>/usb_cam/image_view</strong>” in the drop-down menu.</p><img loading="lazy" height="378" width="604" class="common_img" src="'+m+'" style="width:800px;"><img loading="lazy" height="317" width="420" class="common_img" src="'+h+'" style="width:800px;"></li><li><p>Camera returned image will show up.</p><img loading="lazy" height="1017" width="1920" class="common_img" src="'+p+'" style="width:800px;"></li><li><p>If you need to close the camera returned image, press “<strong>Ctrl+C</strong>”. If it cannot be closed, please try again.</p></li></ol><h2 id="_11-2-lesson-2-camera-calibration" tabindex="-1">11.2 Lesson 2 Camera Calibration <a class="header-anchor" href="#_11-2-lesson-2-camera-calibration" aria-label="Permalink to &quot;11.2 Lesson 2 Camera Calibration&quot;">​</a></h2><p>Usually, there are two ways to calibrate the camera. One is to use the camera to capture the chessboard in real time, the other is to use the pictures of chessboard already required for calibration. And detailed explanation for the first method will be offered in this lesson.</p><p>Note: please print the chessboard pictures stored in the same directory before calibration.</p><p><img loading="lazy" height="44" width="44" src="'+g+'" style="width:50px;">The input command should be case sensitive, and the keywords can be complemented by “<strong>Tab</strong>” key.</p><ol><li><p>Start JetMax, and then connect to ubuntu desktop through NoMachine.</p></li><li><p>Click <img loading="lazy" height="66" width="69" class="inline-icon" src="'+d+'"> or press “<strong>Ctrl+Alt+T</strong>” to open command line terminal.</p></li><li><p>Open a new terminal, and input command “<strong>rosrun camera_calibration cameracalibrator.py --size 8x6 --square 0.014 image:=usb_cam/image_raw camera:=/usb_cam</strong>”.</p></li></ol><p>The value of “<strong>size</strong>” is equal to the number of intersection of the horizontal and vertical lines. In the picture below, there are 8 red points and 6 yellow points, therefore the size of this picture is 8x6.</p><p><img loading="lazy" height="411" width="585" class="common_img" src="'+u+'" style="width:800px;" alt="IMG_256"> <img loading="lazy" height="415" width="590" src="'+A+'" style="width:800px;" alt="IMG_256"></p><p>“square” represents the side length of each square in meter. You can use the ruler to measure the side length of the square. For example, the measured distance is 1.4cm, and you need to set the value of square as 0.014.</p><img loading="lazy" height="342" width="504" class="common_img" src="'+w+'" style="width:800px;" alt="图片5"><p>Having finished input, start the program of camera calibration.</p><img loading="lazy" height="59" width="573" class="common_img" src="'+b+'" style="width:600px;"><ol start="4"><li><p>Face the chessboard picture horizontally to the camera while quickly move and tilt the picture till the parameters of x, y, size and scale at right turn green. Then click “<strong>calibrate</strong>” to start calculating the calibration.</p><p><strong>Note: the time taken to calculate the calibration depends on the quantity of the pictures to be calibrated. The more pictures, the longer it takes.</strong></p><p>Parameter “<strong>x</strong>” represents the right and left zone of the camera field of view, and we need to move the chessboard left and right. Parameter “<strong>y</strong>” indicates top and bottom zone of the camera field of view, and we need to move the chessboard up and down. Parameter “<strong>size</strong>” is the distance between the picture and the camera, and we need to move the picture away from or close to the camera. Parameter “<strong>scale</strong>” stands for the tilt of the picture, and we need to tilt the picture at any angle while keeping the chessboard horizontal.</p><img loading="lazy" height="769" width="1204" class="common_img" src="'+y+'" style="width:800px;"></li><li><p>After the program has finished calculated the calibration, you can move the picture within the camera frame to check whether the picture is displayed normally without Fisheye effect. Having finished calibration, click “commit” to save the data.</p><img loading="lazy" height="694" width="1094" class="common_img" src="'+f+'" style="width:800px;"></li></ol>',20)])])}const v=t(x,[["render",_]]);export{L as __pageData,v as default};
